import{_ as e,b as a,c as o,I as r}from"./chunks/framework.C6cPs9Ia.js";const q=JSON.parse('{"title":"聊聊 QQ 飞车","description":"一个高中生的 QQ 飞车随笔——入坑经历、漂移心得与周末开黑","frontmatter":{"title":"聊聊 QQ 飞车","date":"2026-09-16T00:00:00.000Z","tags":["QQ飞车","游戏","日常"],"cover":"/LQY/images/cover-d.jpg","head":[["meta",{"name":"description","content":"一个高中生的 QQ 飞车随笔——入坑经历、漂移心得与周末开黑"}],["meta",{"name":"keywords","content":"QQ飞车, 赛车游戏, 段位, 漂移, 游戏"}]]},"headers":[],"relativePath":"posts/qq-speed.md","filePath":"posts/qq-speed.md"}'),s={name:"posts/qq-speed.md"};function l(i,t,n,p,d,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<p>周六晚上又和同学跑了几把，趁手感还热乎，写写这个我断断续续玩了很久的游戏。</p><hr><h2 id="入坑经历" tabindex="-1">入坑经历 <a class="header-anchor" href="#入坑经历" aria-label="Permalink to &quot;入坑经历&quot;">​</a></h2><p>最早是在亲戚家的电脑上玩到端游版本。那时候连漂移是什么都不知道，全程贴墙走，输了也很开心。后来自己有了手机，转战手游，才慢慢算是入了门。</p><p>现在的状态：</p><ul><li><strong>段位</strong>：在钻石和星耀之间来回，上得去也守不住</li><li><strong>常用车</strong>：A 车里挑了辆蓝色涂装的，纯个人喜好</li><li><strong>常跑地图</strong>：十一城（弯道多，练技术）、滨海沙滩（老图，有感情了）、西部矿山</li></ul><h2 id="一些心得" tabindex="-1">一些心得 <a class="header-anchor" href="#一些心得" aria-label="Permalink to &quot;一些心得&quot;">​</a></h2><p>新手期看了很多教学视频，什么&quot;最佳漂移角度&quot;&quot;双喷衔接&quot;，看完感觉自己会了，上手照样撞墙。后来才明白，这种东西靠的是肌肉记忆，不是看懂了就行的。</p><p>给还在练的玩家三条实在建议：</p><ol><li><strong>别贪氮气</strong>。攒下来的氮气留到出弯用，弯道中途喷基本等于送。</li><li><strong>提前入弯</strong>。你以为的最佳路线，其实已经晚了半个车身。</li><li><strong>失误了别松手</strong>。轻擦墙靠拉方向还能救回来，一慌松手就真撞死了。</li></ol><h2 id="周五开黑" tabindex="-1">周五开黑 <a class="header-anchor" href="#周五开黑" aria-label="Permalink to &quot;周五开黑&quot;">​</a></h2><p>周五晚上是固定开黑时间，三个同学，语音里一半在报弯道，一半在互相甩锅。</p><p>最经典的一次：领跑的同学在最后一个弯道失误撞墙，被我们仨连环超过，赛后语音安静了几秒，然后他说：&quot;我这是给你们让路。&quot;</p><p>行吧，慈善赛。</p><div class="tip custom-block"><p class="custom-block-title">一点小原则</p><ul><li>周内不玩，周末放开玩，这样两边都踏实</li><li>输了不摔手机，摔了就没得玩了</li><li>段位可以掉，礼貌不能掉，开局&quot;GL&quot;，结束&quot;GG&quot;</li></ul></div><h2 id="为什么一直没弃坑" tabindex="-1">为什么一直没弃坑 <a class="header-anchor" href="#为什么一直没弃坑" aria-label="Permalink to &quot;为什么一直没弃坑&quot;">​</a></h2><p>想了想，大概是因为它节奏快、单局短，很适合高中生的碎片时间。跑一局四五分钟，赢也好输也好，结束就结束，不黏人。</p><p>哪天在赛道上遇到一辆开得又稳又慢的蓝色小车，说不定就是我，在练新图。</p><p>GG，下把见。</p>',19)])])}const h=e(s,[["render",l]]);export{q as __pageData,h as default};
